mapper.select:
SELECT er.id, er.student_name as studentName, er.score, er.exam_id as examId, p.name as paperName, p.total_score as paperTotalScore, er.start_time as startTime, er.end_time as endTime,
CASE WHEN er.end_time IS NOT NULL AND er.start_time IS NOT NULL THEN TIMESTAMPDIFF(MINUTE,er.start_time, er.end_time) ELSE NULL END as duration FROM exam_records er LEFT JOIN paper p ON er.exam_id = p.id WHERE er.status = '已批阅'
AND er.exam_id = #{paperId}
ORDER BY er.score DESC,duration ASC
LIMIT #{limit}
